function SynchronizedTooltip() {
  // Shared between every chart. `[]` when no chart is hovered.
  const [highlightedAxis, setHighlightedAxis] = React.useState([]);
  const dataIndex = highlightedAxis[0]?.dataIndex ?? null;

  const popperRef = React.useRef(null);
  const positionRef = React.useRef({ x: 0, y: 0 });

  const handlePointerMove = (event) => {
    positionRef.current = { x: event.clientX, y: event.clientY };
    popperRef.current?.update();
  };

  const anchorEl = React.useMemo(
    () => ({
      getBoundingClientRect: () => ({
        x: positionRef.current.x,
        y: positionRef.current.y,
        top: positionRef.current.y,
        left: positionRef.current.x,
        right: positionRef.current.x,
        bottom: positionRef.current.y,
        width: 0,
        height: 0,
        toJSON: () => '',
      }),
    }),
    [],
  );

  return (
    <Stack sx={{ width: '100%' }} onPointerMove={handlePointerMove}>
      {charts.map((chart) => (
        <LineChart
          key={chart.id}
          height={160}
          margin={{ top: 10, bottom: 10 }}
          series={[
            {
              id: chart.id,
              data: chart.data,
              label: chart.label,
              color: chart.color,
              showMark: false,
              valueFormatter: (value) =>
                value === null ? '' : chart.valueFormatter(value),
            },
          ]}
          xAxis={[
            {
              id: X_AXIS_ID,
              scaleType: 'point',
              data: months,
              // Only the last chart displays the shared axis labels.
              tickLabelStyle:
                chart.id === charts[charts.length - 1].id
                  ? undefined
                  : { display: 'none' },
            },
          ]}
          yAxis={[{ width: 52 }]}
          axisHighlight={{ x: 'line' }}
          // Disable the built-in tooltip, a single one is rendered below.
          slotProps={{ tooltip: { trigger: 'none' } }}
          highlightedAxis={highlightedAxis}
          onHighlightedAxisChange={setHighlightedAxis}
          hideLegend
        />
      ))}

      <NoSsr>
        <Popper
          open={dataIndex !== null}
          placement="right-start"
          anchorEl={anchorEl}
          popperRef={popperRef}
          modifiers={popperModifiers}
          sx={{ pointerEvents: 'none', zIndex: (theme) => theme.zIndex.modal }}
        >
          {dataIndex !== null && (
            <Paper elevation={2} sx={{ p: 1.5, minWidth: 160 }}>
              <Typography sx={{ fontWeight: 'medium', mb: 0.5 }}>
                {months[dataIndex]}
              </Typography>
              <Stack spacing={0.5}>
                {charts.map((chart) => (
                  <Stack
                    key={chart.id}
                    direction="row"
                    spacing={1}
                    sx={{ alignItems: 'center' }}
                  >
                    <div
                      style={{
                        width: 10,
                        height: 10,
                        borderRadius: 2,
                        backgroundColor: chart.color,
                      }}
                    />
                    <Typography sx={{ flexGrow: 1, fontWeight: 'light' }}>
                      {chart.label}
                    </Typography>
                    <Typography>
                      {chart.valueFormatter(chart.data[dataIndex])}
                    </Typography>
                  </Stack>
                ))}
              </Stack>
            </Paper>
          )}
        </Popper>
      </NoSsr>
    </Stack>
  );
}

